using Microsoft.Extensions.VectorData;

public class KnowledgeChunkRecord
{
    [VectorStoreRecordKey]
    public string Id { get; set; } = Guid.NewGuid().ToString();

    [VectorStoreRecordData(IsFilterable = true)]
    public string DocumentId { get; set; } = string.Empty;

    [VectorStoreRecordData(IsFilterable = true)]
    public string TenantId { get; set; } = string.Empty;

    [VectorStoreRecordData(IsFullTextSearchable = true)]
    public string Content { get; set; } = string.Empty;

    [VectorStoreRecordData(IsFilterable = true)]
    public string[] SecurityGroups { get; set; } = [];

    [VectorStoreRecordVector(1536, DistanceFunction.CosineSimilarity)]
    public ReadOnlyMemory<float> Embedding { get; set; }
}

using Microsoft.Extensions.VectorData;
using Microsoft.Extensions.AI;

public class VectorKnowledgeService
{
    private readonly IVectorStoreRecordCollection<string, KnowledgeChunkRecord> _collection;
    private readonly IEmbeddingGenerator<string, Embedding<float>> _embeddingGenerator;

    public VectorKnowledgeService(
        IVectorStore vectorStore,
        IEmbeddingGenerator<string, Embedding<float>> embeddingGenerator)
    {
        _collection = vectorStore.GetCollection<string, KnowledgeChunkRecord>("enterprise_knowledge");
        _embeddingGenerator = embeddingGenerator;
    }

    public async Task InitializeCollectionAsync(CancellationToken ct = default)
    {
        // Ensure the vector index and schema are created in the underlying database
        await _collection.CreateCollectionIfNotExistsAsync(ct);
    }

    public async Task IngestChunkAsync(string docId, string tenantId, string content, string[] roles, CancellationToken ct = default)
    {
        var embeddingResult = await _embeddingGenerator.GenerateEmbeddingAsync(content, cancellationToken: ct);

        var record = new KnowledgeChunkRecord
        {
            Id = $"{docId}_{Guid.NewGuid():N}",
            DocumentId = docId,
            TenantId = tenantId,
            Content = content,
            SecurityGroups = roles,
            Embedding = embeddingResult.Vector
        };

        await _collection.UpsertAsync(record, cancellationToken: ct);
    }

    public async Task<List<KnowledgeChunkRecord>> SearchAsync(
        string query,
        string tenantId,
        int topK = 5,
        CancellationToken ct = default)
    {
        var queryEmbedding = await _embeddingGenerator.GenerateEmbeddingAsync(query, cancellationToken: ct);

        var searchOptions = new VectorSearchOptions<KnowledgeChunkRecord>
        {
            VectorPropertyName = nameof(KnowledgeChunkRecord.Embedding),
            Top = topK,
            Filter = new VectorSearchFilter()
                .EqualTo(nameof(KnowledgeChunkRecord.TenantId), tenantId)
        };

        var results = new List<KnowledgeChunkRecord>();
        await foreach (var result in _collection.VectorizedSearchAsync(queryEmbedding.Vector, searchOptions, ct))
        {
            results.Add(result.Record);
        }

        return results;
    }
}
